"""Credit pricing replaces the obsolete month-license content after legacy page transforms."""
credit_page=next(page for page in pages if page['slug']=='pricing')
credit_page.update(title='Kredi paketleri ve fiyatlar | Veri Burada',description='100, 1.000, 5.000 ve 10.000 kredilik Veri Burada paketlerini ve birim fiyatlarını karşılaştırın.',h1='İhtiyacınız kadar kredi.<br><em>Size uygun paket.</em>',lead='1 kredi, 1 işletme kaydı. Kredilerinizi süre sınırı olmadan kullanın.',scene=None)
credit_packages=[('100','Başlangıç','100','200','2,00'),('1000','Düzenli araştırma','1.000','1.200','1,20'),('5000','Profesyonel','5.000','5.000','1,00'),('10000','Kurumsal','10.000','8.000','0,80')]
credit_page['body']='<section class="credit-details-section"><div class="credit-detail-grid">'+''.join(f'<article class="credit-detail-card" data-credit-package="{key}"><span>{tier}</span><h2>{amount}<small>kredi</small></h2><strong>{total} TL</strong><p>{unit} TL / kredi</p><a class="button primary" data-auth-signup href="https://app.veriburada.com/signup">Hesap oluştur</a></article>' for key,tier,amount,total,unit in credit_packages)+'</div></section>'+block('Her pakette aynı bilgiler.',paras('Telefon, adres, web sitesi ve puan bilgileriyle işletmeleri bir arada inceleyin. Bir kaydın içeriği, işletme profilinde bulunan bilgilere bağlıdır.','Hazırlanan listenizi CSV olarak dışa aktarabilir, Excel ve benzeri araçlarla açabilirsiniz.'))+block('Krediler hakkında.',faq([('Kredi nasıl kullanılır?','Bir kredi, bir detaylı işletme kaydını temsil eder. Paketler arasındaki fark kredi miktarı ve birim fiyatıdır.'),('Krediler ne kadar süre geçerli?','Paketler belirli bir aylık kullanım süresine bağlı değildir. Kredilerinizi ihtiyaç duyduğunuz zaman kullanabilirsiniz.'),('Hesabımı nasıl açarım?','Hesap oluştur düğmesi Veri Burada uygulamasındaki kayıt sayfasını açar. Mevcut hesabınız varsa üst menüden giriş yapabilirsiniz.'),('Örnek dosyayı inceleyebilir miyim?','Örnek listeler sayfasından dosyanın sütun yapısını inceleyebilir ve örnek CSV dosyasını indirebilirsiniz.')]))
